"""DEC-10: document the iOS legacy theme template (acknowledged only, not built in Figma, tokens or code).
Usage: python3 scripts/build_legacy_doc.py   (after build_type_tokens.py)
Reads data/legacy-template-type.json, data/source/button-shipped.json; writes docs/LEGACY-TEMPLATE.md.
"""
import json
T = json.load(open('data/legacy-template-type.json'))
B = json.load(open('data/source/button-shipped.json'))['primary']['ios']
L = ['# iOS legacy theme template (acknowledged only)', '',
     'Generated by `scripts/build_legacy_doc.py`. Do not edit by hand.', '',
     f"Seven iOS markets ({', '.join(T['markets'])}) still run TroncKit's older theme template (Style.json, 60–61 keys) instead of the standard template the other 70 markets use. "
     'These values ship today, so they are recorded here. Per DEC-10 (Karl, 2026-11-03) they are **not** built in Figma, tokens or code, because the template should go away (IMPROVEMENTS TYPE-01). '
     'Designs for these markets use the standard styles. Source: the iOS style guide notes ("Legacy template (BS, DP, …): …").', '',
     '## Primary button', '', '| Part | Standard | Legacy template |', '|---|---|---|',
     f"| Corner radius | {B['radius']} pt | {B['radius_legacy']} pt |", f"| Border | none | {B['border_legacy']} pt in the fill color |", '',
     '## Text styles', '', '| Role | iOS style | Standard | Legacy template |', '|---|---|---|---|']
for r in T['type']:
    L.append(f"| {r['role'].replace('Legacy: ', '')} | `{r['style']}` | {r['standard'] or '— (legacy only)'} | {r['legacy']} |")
open('docs/LEGACY-TEMPLATE.md', 'w').write('\n'.join(L) + '\n')
print(len(T['type']), 'type rows')
